var ax = await wps.getAXState({emit:false, disableDiffing:true});
var axLines = ax.split(/\n/);
var numbered = axLines.filter(l => /^\s*\d+\s/.test(l));
var roles = [];
for (const l of numbered) {
  const m = l.match(/^\s*\d+\s+([^\s,]+)/);
  if (m && !roles.includes(m[1])) roles.push(m[1]);
}
var axSummary = {
  attempted: true,
  element_count: numbered.length,
  roles,
  excerpt: axLines.slice(0, Math.min(10, axLines.length)).join("\n")
};
nodeRepl.write(axSummary);

var mainClick = {attempted:true, hit:false, error:null};
try {
  await wps.click([1000,700]);
  var afterClick = await wps.getAXState({emit:false, disableDiffing:true});
  mainClick.hit = afterClick.includes('标准窗口 首页');
  if (!mainClick.hit) mainClick.error = '点击后未观察到主窗口“首页”';
} catch (e) {
  mainClick.error = String(e);
}
nodeRepl.write(mainClick);

