var menuProbe = {attempted:true, label:"帮助", opened:false, error:null};
try {
  await wps.click(47);
  await new Promise(r => setTimeout(r, 300));
  var menuState = await wps.getAXStateAndScreenshot({emit:false, disableDiffing:true});
  menuProbe.opened = /Window:/.test(menuState.state) && /菜单|帮助|关于|检查|更新/.test(menuState.state);
  nodeRepl.write({probe:menuProbe, state:menuState.state});
  if (menuState.screenshot) await nodeRepl.emitImage(menuState.screenshot);
} catch (e) {
  menuProbe.error = String(e);
  nodeRepl.write(menuProbe);
}

var shortcutProbe = {attempted:true, keys:["Command","F"], delivered:false, error:null};
try {
  await wps.pressKey("Escape");
  await new Promise(r => setTimeout(r, 150));
  await wps.pressKey("Meta+f");
  await new Promise(r => setTimeout(r, 300));
  var shortcutState = await wps.getAXStateAndScreenshot({emit:false, disableDiffing:true});
  shortcutProbe.delivered = true;
  nodeRepl.write({probe:shortcutProbe, state:shortcutState.state});
  if (shortcutState.screenshot) await nodeRepl.emitImage(shortcutState.screenshot);
} catch (e) {
  shortcutProbe.error = String(e);
  nodeRepl.write(shortcutProbe);
}

